CREATE TABLE public.push_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,endpoint text NOT NULL UNIQUE,p256dh text NOT NULL,auth text NOT NULL,user_agent text,created_at timestamptz NOT NULL DEFAULT now(),last_success_at timestamptz,fail_count integer NOT NULL DEFAULT 0);
GRANT SELECT,DELETE ON public.push_subscriptions TO authenticated; GRANT ALL ON public.push_subscriptions TO service_role; ALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY push_owner_select ON public.push_subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY push_owner_delete ON public.push_subscriptions FOR DELETE TO authenticated USING(user_id=auth.uid()); CREATE INDEX push_owner_idx ON public.push_subscriptions(user_id);
ALTER TABLE public.notification_prefs ADD COLUMN raceday_enabled boolean NOT NULL DEFAULT false, ADD COLUMN raceday_opted_in_at timestamptz;
COMMENT ON COLUMN public.notification_prefs.raceday_alerts IS 'DEPRECATED: legacy default is not consent; use raceday_enabled with explicit opt-in.';
CREATE TABLE public.raceday_notifications(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL,event_key text NOT NULL,sent_telegram_at timestamptz,sent_push_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_key));
GRANT SELECT ON public.raceday_notifications TO authenticated; GRANT ALL ON public.raceday_notifications TO service_role;GRANT USAGE,SELECT ON SEQUENCE public.raceday_notifications_id_seq TO service_role;ALTER TABLE public.raceday_notifications ENABLE ROW LEVEL SECURITY;CREATE POLICY raceday_owner_select ON public.raceday_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.push_test_requests(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.push_test_requests TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.push_test_requests_id_seq TO service_role;ALTER TABLE public.push_test_requests ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.reserve_push_test(uid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,551));IF (SELECT count(*) FROM public.push_test_requests WHERE user_id=uid AND created_at>now()-interval '1 hour')>=5 THEN RAISE EXCEPTION 'TEST_LIMIT';END IF;INSERT INTO public.push_test_requests(user_id) VALUES(uid);END $$;
REVOKE ALL ON FUNCTION public.reserve_push_test(uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.reserve_push_test(uuid) TO service_role;
CREATE FUNCTION public.save_push_subscription(uid uuid,ep text,pkey text,akey text,agent text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,552));
IF EXISTS(SELECT 1 FROM public.push_subscriptions WHERE endpoint=ep AND user_id<>uid) THEN RAISE EXCEPTION 'DEVICE_LINKED_TO_ANOTHER_ACCOUNT';END IF;
INSERT INTO public.push_subscriptions(user_id,endpoint,p256dh,auth,user_agent) VALUES(uid,ep,pkey,akey,left(agent,500)) ON CONFLICT(endpoint) DO UPDATE SET p256dh=excluded.p256dh,auth=excluded.auth,user_agent=excluded.user_agent,fail_count=0;
DELETE FROM public.push_subscriptions WHERE id IN (SELECT id FROM public.push_subscriptions WHERE user_id=uid ORDER BY created_at DESC,id DESC OFFSET 10);
INSERT INTO public.notification_prefs(user_id,push_enabled) VALUES(uid,true) ON CONFLICT(user_id) DO UPDATE SET push_enabled=true;END $$;
REVOKE ALL ON FUNCTION public.save_push_subscription(uuid,text,text,text,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.save_push_subscription(uuid,text,text,text,text) TO service_role;